window.YildizExamBank = [
  /* ================= İLK YARDIM ================= */
  { id: 'iy01', s: 'iy', q: 'İlk yardımın temel uygulamaları hangi sırayla yapılır?', o: ['Koruma → Bildirme → Kurtarma', 'Bildirme → Kurtarma → Koruma', 'Kurtarma → Koruma → Bildirme', 'Koruma → Kurtarma → Bildirme'], a: 0, e: 'İlk yardımın temel uygulamaları sırasıyla Koruma, Bildirme ve Kurtarma’dır (KBK). Önce olay yeri güvenli hâle getirilir, sonra 112 aranır, ardından kazazedeye müdahale edilir.' },
  { id: 'iy02', s: 'iy', v: 'fa:tel112', q: 'Kaza yerinden ambulans çağırmak için hangi numara aranır?', o: ['112', '155', '110', '156'], a: 0, e: '112 Acil Çağrı Merkezi aranarak ambulans istenir. Arayan kişi kendini tanıtır, olay yerini ve kazazedelerin durumunu açıkça bildirir.' },
  { id: 'iy03', s: 'iy', q: '112 arandığında aşağıdakilerden hangisinin bildirilmesi gerekmez?', o: ['Kazazedelerin kimlik numaraları', 'Olayın yeri (açık adres ve yol tarifi)', 'Kazazede sayısı ve durumları', 'Arayanın adı ve telefon numarası'], a: 0, e: 'Sakin bir şekilde olay yeri, olayın ne olduğu, kazazede sayısı ve durumu, yapılan ilk yardım ile arayanın adı ve telefonu bildirilir. Kimlik numaraları istenmez.' },
  { id: 'iy04', s: 'iy', q: 'Trafik kazası yerine ulaşan ilk yardımcının ilk işi aşağıdakilerden hangisi olmalıdır?', o: ['Olay yerinin güvenliğini sağlamak (kontak kapatma, uyarı reflektörü koyma vb.)', 'Kazazedeleri hemen araçtan çıkarmak', 'Kazazedelere su içirmek', 'Kazazedeleri özel araçla hastaneye götürmek'], a: 0, e: 'Koruma aşamasında önce kendi güvenliğini ve olay yerinin güvenliğini sağlarsın: kontaklar kapatılır, sigara içilmez, reflektör ve dörtlülerle diğer sürücüler uyarılır.' },
  { id: 'iy05', s: 'iy', q: 'Kazazedenin bilinç kontrolü nasıl yapılır?', o: ['Omuzlarına hafifçe dokunup “İyi misiniz?” diye seslenilir', 'Yüzüne su dökülür', 'Kazazede sertçe sarsılır', 'Kazazedeye kolonya koklatılır'], a: 0, e: 'Bilinç kontrolü, omuzlara hafifçe dokunup yüksek sesle “İyi misiniz?” diye seslenerek yapılır. Sarsmak, su dökmek ve kolonya koklatmak yanlıştır.' },
  { id: 'iy06', s: 'iy', v: 'fa:basgeri', q: 'Bilinci kapalı kazazedede hava yolunu açmak için hangi yöntem uygulanır?', o: ['Baş geri – çene yukarı pozisyonu', 'Başın göğse doğru eğilmesi', 'Kazazedenin oturtulması', 'Ayakların yukarı kaldırılması'], a: 0, e: 'Bir el alna konup baş geriye itilir, diğer elin iki parmağıyla çene yukarı kaldırılır. Böylece dilin hava yolunu kapatması önlenir.' },
  { id: 'iy07', s: 'iy', fix: 1, q: 'Solunum kontrolü “bak – dinle – hisset” yöntemiyle en fazla kaç saniye süreyle yapılır?', o: ['3', '10', '30', '60'], a: 1, e: 'Hava yolu açıldıktan sonra göğüs hareketlerine bakılır, soluk sesi dinlenir ve yanakta hissedilir. Bu kontrol en fazla 10 saniye sürer.' },
  { id: 'iy08', s: 'iy', v: 'fa:cpr', q: 'Yetişkin bir kazazedeye temel yaşam desteği uygulanırken göğüs basısı ve suni solunum hangi oranda yapılır?', o: ['30 : 2', '15 : 2', '5 : 1', '30 : 1'], a: 0, e: 'Yetişkinlerde 30 göğüs basısının ardından 2 suni solunum yapılır ve bu döngü sağlık ekibi gelene ya da kazazede kendine gelene kadar sürdürülür.' },
  { id: 'iy09', s: 'iy', fix: 1, q: 'Yetişkinde göğüs basısı dakikada kaç kez olacak hızda uygulanmalıdır?', o: ['30 – 40', '60 – 80', '100 – 120', '150 – 180'], a: 2, e: 'Göğüs basısı dakikada 100–120 kez olacak şekilde, her basıdan sonra göğsün eski hâline dönmesine izin verilerek uygulanır.' },
  { id: 'iy10', s: 'iy', fix: 1, q: 'Yetişkinde göğüs basısı yapılırken göğüs kemiği yaklaşık kaç cm aşağı inecek şekilde bastırılır?', o: ['1 – 2 cm', '2 – 3 cm', '5 – 6 cm', '8 – 10 cm'], a: 2, e: 'Yetişkinde göğüs kemiği 5–6 cm aşağı inecek şekilde, kollar dirsekten bükülmeden ve vücut ağırlığı kullanılarak bastırılır.' },
  { id: 'iy11', s: 'iy', q: 'Yetişkinde göğüs basısı için eller nereye yerleştirilir?', o: ['Göğüs kemiğinin alt yarısına (göğsün ortası)', 'Karnın üst kısmına', 'Sol göğsün üzerine', 'Sağ kaburgaların üzerine'], a: 0, e: 'Bir elin topuğu göğüs kemiğinin alt yarısına (göğsün ortasına) konur, diğer el üstüne yerleştirilip parmaklar kenetlenir.' },
  { id: 'iy12', s: 'iy', q: 'Göğüs basısı nasıl uygulanmalıdır?', o: ['Kollar dirsekten bükülmeden, omuzlar göğsün üzerinde olacak şekilde vücut ağırlığıyla', 'Kollar dirsekten bükülerek, yalnızca kol gücüyle', 'Tek parmakla ve hafifçe', 'Yumrukla göğse vurarak'], a: 0, e: 'Omuzlar ellerin tam üzerinde, kollar dik olmalıdır. Vücut ağırlığıyla yapılan bası hem etkili olur hem de ilk yardımcıyı yormaz.' },
  { id: 'iy13', s: 'iy', v: 'fa:koma', q: 'Bilinci kapalı ancak solunumu olan kazazedeye hangi pozisyon verilir?', o: ['Derlenme (koma) pozisyonu', 'Sırtüstü yatırıp ayakları yükseltme', 'Yarı oturuş pozisyonu', 'Yüzüstü yatırma'], a: 0, e: 'Derlenme (koma) pozisyonu, kusması hâlinde kazazedenin boğulmasını ve dilin hava yolunu tıkamasını önler. Solunumu düzenli aralıklarla kontrol edilir.' },
  { id: 'iy14', s: 'iy', v: 'fa:sok', q: 'Şok belirtileri gösteren ve bilinci açık olan kazazedeye hangi pozisyon verilir?', o: ['Sırtüstü yatırılıp ayakları yaklaşık 30 cm yükseltilir', 'Oturtulup başı öne eğilir', 'Yüzüstü yatırılır', 'Ayağa kaldırılıp yürütülür'], a: 0, e: 'Şok pozisyonunda kazazede sırtüstü yatırılır, ayakları yaklaşık 30 cm yükseltilir ve üzeri örtülerek ısı kaybı önlenir.' },
  { id: 'iy15', s: 'iy', q: 'Aşağıdakilerden hangisi şok belirtisidir?', o: ['Soğuk, soluk ve nemli deri; hızlı ve zayıf nabız', 'Kızarmış ve sıcak deri', 'Yavaş ve güçlü nabız', 'Vücut ısısında yükselme'], a: 0, e: 'Şokta deri soğuk, soluk ve nemlidir; nabız hızlı ve zayıflar, solunum hızlanır. Kazazede huzursuz olabilir, susuzluk hissedebilir.' },
  { id: 'iy16', s: 'iy', q: 'Dış kanamalarda ilk uygulanacak yöntem hangisidir?', o: ['Kanayan yere temiz bir bezle doğrudan baskı uygulamak', 'Hemen turnike uygulamak', 'Yaraya pamuk bastırmak', 'Yarayı bol suyla yıkamak'], a: 0, e: 'Dış kanamada önce kanayan yere temiz bir bezle doğrudan baskı uygulanır. Yaraya pamuk konmaz; turnike yalnızca durdurulamayan uzuv kanamalarında son çaredir.' },
  { id: 'iy17', s: 'iy', q: 'Turnike uygulamasıyla ilgili hangisi doğrudur?', o: ['Diğer yöntemlerle durdurulamayan kol ve bacak kanamalarında uygulanır, uygulama saati not edilir', 'Her kanamada ilk olarak uygulanır', 'Boyun kanamalarında uygulanır', 'Küçük sıyrıklarda uygulanır'], a: 0, e: 'Turnike, uzuv kopması gibi baskıyla durdurulamayan kol ve bacak kanamalarında son çare olarak uygulanır; uygulama saati görünür bir yere yazılır.' },
  { id: 'iy18', s: 'iy', v: 'fa:burun', q: 'Burun kanamasında kazazedeye ne yapılmalıdır?', o: ['Oturtulup başı hafifçe öne eğilir, burun kanatları yaklaşık 5 dakika sıkılır', 'Başı geriye yatırılır', 'Sırtüstü yatırılıp ayakları kaldırılır', 'Burnuna pamuk tıkanıp başı geriye atılır'], a: 0, e: 'Baş öne eğilerek kanın boğaza kaçması önlenir; burun kanatları yaklaşık 5 dakika sıkılır. Kanama durmazsa sağlık kuruluşuna başvurulur.' },
  { id: 'iy19', s: 'iy', v: 'fa:yanik', q: 'Isı ile oluşan yanıklarda ilk yardım olarak ne yapılmalıdır?', o: ['Yanık bölge en az 20 dakika soğuk (çeşme) suyla soğutulur', 'Yanık üzerine diş macunu veya yoğurt sürülür', 'Oluşan su kabarcıkları patlatılır', 'Yanık bölge buzla ovulur'], a: 0, e: 'Yanık bölge en az 20 dakika soğuk suyla soğutulur; takılar çıkarılır. Kabarcıklar patlatılmaz, yanığa diş macunu, yoğurt gibi maddeler sürülmez.' },
  { id: 'iy20', s: 'iy', q: 'Kırık şüphesi olan bölgeye ilk yardımda ne yapılır?', o: ['Olduğu pozisyonda, bir üst ve bir alt eklemi içine alacak şekilde tespit edilir', 'Kırık uçlar yerine oturtulmaya çalışılır', 'Bölgeye masaj yapılır', 'Kazazede yürütülerek kontrol edilir'], a: 0, e: 'Kırık bölge bulunduğu şekilde, bir üst ve bir alt eklemi de içine alacak biçimde tespit edilir. Kırığı düzeltmeye çalışmak damar ve sinirlere zarar verebilir.' },
  { id: 'iy21', s: 'iy', q: 'Trafik kazasında omurga yaralanmasından şüphelenilen kazazedeye nasıl davranılır?', o: ['Baş–boyun–gövde ekseni korunur, zorunlu olmadıkça hareket ettirilmez', 'Hemen oturtulur', 'Başı öne eğilir', 'Ayağa kaldırılır'], a: 0, e: 'Omurga yaralanması şüphesinde baş–boyun–gövde ekseni bozulmadan korunur. Yangın gibi hayati bir tehlike yoksa kazazede yerinden oynatılmaz.' },
  { id: 'iy22', s: 'iy', q: 'Araç içinde sıkışmış ve yangın gibi hayati bir tehlikeyle karşı karşıya olan kazazedeyi araçtan çıkarmak için hangi yöntem kullanılır?', o: ['Rautek manevrası', 'Heimlich manevrası', 'Şok pozisyonu', 'Baş geri – çene yukarı pozisyonu'], a: 0, e: 'Rautek manevrası, hayati tehlike olduğunda kazazedeyi baş–boyun–gövde eksenini koruyarak araçtan hızla çıkarmak için kullanılır.' },
  { id: 'iy23', s: 'iy', v: 'fa:heimlich', q: 'Bilinci açık bir yetişkinde yabancı cisimle hava yolu tamamen tıkanırsa hangi uygulama yapılır?', o: ['Sırtına 5 kez vurulur, ardından 5 kez karın basısı (Heimlich) uygulanır', 'Hemen su içirilir', 'Sırtüstü yatırılıp ayakları kaldırılır', 'Parmakla boğazı zorlanarak kusturulmaya çalışılır'], a: 0, e: 'Kazazede öksüremiyor ve konuşamıyorsa önce kürek kemiklerinin arasına 5 kez vurulur, cisim çıkmazsa 5 kez karın basısı (Heimlich manevrası) yapılır.' },
  { id: 'iy24', s: 'iy', q: 'Yabancı cisim nedeniyle hava yolu kısmen tıkanan ve öksürebilen kazazedeye ne yapılır?', o: ['Öksürmesi teşvik edilir, başka müdahale yapılmaz', 'Hemen karın basısı yapılır', 'Ağzına parmakla girilip cisim aranır', 'Bol su içirilir'], a: 0, e: 'Kısmi tıkanmada kazazede öksürebiliyorsa öksürmeye teşvik edilir; sırta vurma veya karın basısı yapılmaz, kazazede yakından izlenir.' },
  { id: 'iy25', s: 'iy', q: 'Bayılan kişiye ilk yardımda ne yapılır?', o: ['Sırtüstü yatırılır, ayakları yaklaşık 30 cm kaldırılır ve sıkan giysileri gevşetilir', 'Hemen ayağa kaldırılır', 'Ağzından su verilir', 'Kolonya koklatılıp sarsılır'], a: 0, e: 'Bayılmada kazazede sırtüstü yatırılıp ayakları kaldırılır, sıkan giysiler gevşetilir ve temiz hava sağlanır. Kolonya koklatılmaz, ağızdan bir şey verilmez.' },
  { id: 'iy26', s: 'iy', q: 'Bilinci bulanık kazazedeye aşağıdakilerden hangisi yapılmamalıdır?', o: ['Ağızdan yiyecek veya içecek vermek', 'Solunumunu kontrol etmek', 'Üzerini örterek ısı kaybını önlemek', '112’yi aramak'], a: 0, e: 'Bilinci bulanık veya kapalı kazazedeye ağızdan hiçbir şey verilmez; boğulma tehlikesi vardır.' },
  { id: 'iy27', s: 'iy', q: 'İlk yardımda kullanılan “ABC” değerlendirmesinde “C” harfi neyi ifade eder?', o: ['Dolaşım', 'Bilinç', 'Kanama', 'Kırık'], a: 0, e: 'A: hava yolu (Airway), B: solunum (Breathing), C: dolaşım (Circulation). Değerlendirme bu sırayla yapılır.' },
  { id: 'iy28', s: 'iy', fix: 1, q: 'Sağlıklı bir yetişkinde normal nabız sayısı dakikada kaçtır?', o: ['20 – 30', '30 – 50', '60 – 100', '120 – 160'], a: 2, e: 'Sağlıklı bir yetişkinin nabzı dakikada 60–100 arasındadır.' },
  { id: 'iy29', s: 'iy', fix: 1, q: 'Sağlıklı bir yetişkinde normal solunum sayısı dakikada kaçtır?', o: ['4 – 6', '12 – 20', '30 – 40', '60 – 80'], a: 1, e: 'Sağlıklı bir yetişkin dakikada 12–20 kez soluk alıp verir.' },
  { id: 'iy30', s: 'iy', q: 'Elektrik çarpmasında ilk yapılması gereken nedir?', o: ['Elektrik akımını kesmek', 'Kazazedeye çıplak elle dokunup çekmek', 'Kazazedeyi suyla ıslatmak', 'Kazazedeye su içirmek'], a: 0, e: 'Önce sigorta kapatılarak akım kesilir ya da kuru, yalıtkan bir cisimle kazazede kaynaktan uzaklaştırılır. Akım kesilmeden dokunmak ilk yardımcıyı da çarpar.' },
  { id: 'iy31', s: 'iy', q: 'Göze batmış bir cisim varsa ne yapılır?', o: ['Cisim çıkarılmaz; sabitlenir, her iki göz kapatılarak sağlık kuruluşuna gidilir', 'Cisim hemen çekilerek çıkarılır', 'Göz ovularak cisim çıkarılmaya çalışılır', 'Göze merhem sürülür'], a: 0, e: 'Batan cisim çıkarılmaz, hareket etmeyecek şekilde sabitlenir. Göz hareketlerini azaltmak için iki göz birden kapatılır.' },
  { id: 'iy32', s: 'iy', q: 'Ağızdan zehirlenmelerde ilk yardımla ilgili hangisi doğrudur?', o: ['Kazazede kusturulmaz; 114 Ulusal Zehir Danışma Merkezi aranır', 'Kazazedeye süt içirilip kusturulur', 'Kazazedeye tuzlu su içirilir', 'Kazazede uyutulur'], a: 0, e: 'Zehirlenmelerde kazazede kusturulmaz, ağızdan bir şey verilmez. 114 Ulusal Zehir Danışma Merkezi ve 112 aranarak bilgi alınır.' },
  { id: 'iy33', s: 'iy', q: 'Donmuş bölgeye ilk yardımda aşağıdakilerden hangisi yapılmamalıdır?', o: ['Donmuş bölgeyi ovmak', 'Kazazedeyi ılık bir ortama almak', 'Islak giysileri çıkarmak', 'Kazazedenin üzerini örtmek'], a: 0, e: 'Donmuş bölge ovulmaz; dokular zarar görür. Kazazede ılık ortama alınır, ıslak giysileri çıkarılıp kuru örtülerle ısıtılır.' },

  /* ================= TRAFİK VE ÇEVRE ================= */
  { id: 'tc01', s: 'tc', v: 'sign:dur', q: 'Bu trafik işareti sürücüye neyi bildirir?', o: ['Dur: tamamen durmadan geçme', 'Yol ver', 'Park etmek yasaktır', 'Taşıt giremez'], a: 0, e: 'Kırmızı sekizgen DUR levhasında tamamen durulur; yol kontrol edilip geçiş hakkı olanlara yol verildikten sonra geçilir.' },
  { id: 'tc02', s: 'tc', v: 'sign:yolver', q: 'Kavşağa yaklaşırken bu işaretle karşılaşan sürücü ne yapmalıdır?', o: ['Hızını azaltıp geçiş hakkı olan araçlara yol vermeli', 'Hızını artırıp önce geçmeli', 'Korna çalarak geçmeli', 'Her durumda durup bir dakika beklemeli'], a: 0, e: 'Ters üçgen “Yol ver” işaretidir. Hız azaltılır, gerekirse durulur ve geçiş hakkı olan araçlara yol verilir.' },
  { id: 'tc03', s: 'tc', v: 'sign:girisyok', q: 'Bu işaret neyi bildirir?', o: ['Girişi olmayan yol', 'Tek yönlü yol', 'Duraklamak yasaktır', 'Ana yol bitti'], a: 0, e: 'Kırmızı daire içindeki beyaz yatay bant “Girişi olmayan yol” anlamına gelir; bu yöne taşıtla girilemez.' },
  { id: 'tc04', s: 'tc', v: 'sign:hiz50', q: 'Bu işaret neyi bildirir?', o: ['Azami hız sınırı 50 km/s', 'Asgari hız sınırı 50 km/s', '50 metre sonra kavşak', 'Tavsiye edilen hız 50 km/s'], a: 0, e: 'Kırmızı çerçeveli yuvarlak levha azami hızı gösterir. Asgari hız levhaları mavi zeminlidir.' },
  { id: 'tc05', s: 'tc', v: 'sign:asgari30', q: 'Bu işaret neyi bildirir?', o: ['Asgari hız sınırı 30 km/s', 'Azami hız sınırı 30 km/s', 'Tavsiye edilen hız 30 km/s', '30 metre sonra kavşak'], a: 0, e: 'Mavi zeminli yuvarlak levha mecburiyet bildirir: bu yolda en az 30 km/s hızla gidilmelidir.' },
  { id: 'tc06', s: 'tc', v: 'sign:parkyasak', q: 'Bu işaret neyi bildirir?', o: ['Park etmek yasaktır', 'Duraklamak ve park etmek yasaktır', 'Girişi olmayan yol', 'Taşıt trafiğine kapalı yol'], a: 0, e: 'Mavi zemin üzerindeki tek çapraz çizgi park yasağını gösterir. Çarpı (X) şeklinde iki çizgi varsa duraklamak da yasaktır.' },
  { id: 'tc07', s: 'tc', v: 'sign:durakparkyasak', q: 'Bu işaret neyi bildirir?', o: ['Duraklamak ve park etmek yasaktır', 'Park etmek yasaktır', 'Kavşak yaklaşıyor', 'Taşıt trafiğine kapalı yol'], a: 0, e: 'Mavi zemin üzerindeki çarpı (X) işareti duraklamanın ve park etmenin yasak olduğunu bildirir.' },
  { id: 'tc08', s: 'tc', v: 'sign:anayol', q: 'Sarı eşkenar dörtgen şeklindeki bu işaret neyi bildirir?', o: ['Ana yol', 'Ana yol sonu', 'Dikkat, kavşak var', 'Yol çalışması'], a: 0, e: 'Bu levha “Ana yol”u gösterir; kavşaklarda geçiş hakkı ana yoldaki araçlarındır. Yine de dikkatli olunmalıdır.' },
  { id: 'tc09', s: 'tc', v: 'sign:anayolsonu', q: 'Bu işaret neyi bildirir?', o: ['Ana yol sonu', 'Ana yol', 'Park yeri', 'Kaygan yol'], a: 0, e: 'Çapraz çizgili sarı dörtgen, ana yolun sona erdiğini bildirir; bundan sonra geçiş önceliği genel kurallara göre belirlenir.' },
  { id: 'tc10', s: 'tc', v: 'sign:sollamayasak', q: 'Bu işaret neyi bildirir?', o: ['Öndeki taşıtı geçmek yasaktır', 'İki yönlü trafik', 'Taşıtlar arasında mesafe bırak', 'Çift şeritli yol'], a: 0, e: 'Kırmızı ve siyah iki taşıt resmi bulunan yasaklama levhası, öndeki taşıtı geçmenin (sollamanın) yasak olduğunu gösterir.' },
  { id: 'tc11', s: 'tc', v: 'sign:sagadonulmez', q: 'Bu işaret neyi bildirir?', o: ['Sağa dönülmez', 'Sağa mecburi yön', 'Sağa tehlikeli viraj', 'Sağdan gidiniz'], a: 0, e: 'Kırmızı çerçeveli ve üstü kırmızı çizgiyle çizilmiş sağa ok, sağa dönmenin yasak olduğunu bildirir.' },
  { id: 'tc12', s: 'tc', v: 'sign:udonusu', q: 'Bu işaret neyi bildirir?', o: ['U dönüşü yapmak yasaktır', 'Geri dönüş serbest', 'Sola dönülmez', 'Çıkmaz yol'], a: 0, e: 'Üstü çizilmiş U şeklindeki ok, U dönüşü (geri dönüş) yapmanın yasak olduğunu bildirir.' },
  { id: 'tc13', s: 'tc', v: 'sign:kapali', q: 'İçi boş, kırmızı çerçeveli yuvarlak bu işaret neyi bildirir?', o: ['Taşıt trafiğine kapalı yol', 'Girişi olmayan yol', 'Azami hız sınırlaması sonu', 'Park etmek yasaktır'], a: 0, e: 'Beyaz zeminli, kırmızı çerçeveli ve içi boş yuvarlak levha, yolun her iki yönde taşıt trafiğine kapalı olduğunu bildirir.' },
  { id: 'tc14', s: 'tc', v: 'sign:hizsonu', q: 'Bu işaret neyi bildirir?', o: ['Azami hız sınırlaması sonu', 'Azami hız sınırı 50 km/s', 'Asgari hız sınırlaması', 'Yerleşim yeri sonu'], a: 0, e: 'Gri rakamlı ve üzeri çapraz çizgili levha, daha önce konulmuş azami hız sınırlamasının sona erdiğini bildirir.' },
  { id: 'tc15', s: 'tc', v: 'sign:yasaksonu', q: 'Bu işaret neyi bildirir?', o: ['Bütün yasaklama ve kısıtlamaların sonu', 'Girişi olmayan yol', 'Park etmek yasaktır', 'Taşıt trafiğine kapalı yol'], a: 0, e: 'Beyaz zemin üzerindeki çapraz çizgiler, daha önce konulmuş bütün yasaklama ve kısıtlamaların sona erdiğini bildirir.' },
  { id: 'tc16', s: 'tc', v: 'sign:ileri', q: 'Bu işaret neyi bildirir?', o: ['İleri mecburi yön', 'Tek yönlü yol', 'Sollama serbest', 'Ana yol'], a: 0, e: 'Mavi zeminli yuvarlak levhalar mecburiyet bildirir: bu levhada yalnızca ileri gidilebilir.' },
  { id: 'tc17', s: 'tc', v: 'sign:sagdan', q: 'Bu işaret neyi bildirir?', o: ['Sağdan gidiniz', 'Sağa dönülmez', 'Sağa tehlikeli viraj', 'Sağa mecburi yön'], a: 0, e: 'Aşağı-sağa doğru eğik ok, engelin veya refüjün sağından gidilmesi gerektiğini bildirir.' },
  { id: 'tc18', s: 'tc', v: 'sign:ada', q: 'Bu işaret neyi bildirir?', o: ['Ada etrafında dönünüz', 'U dönüşü yapılabilir', 'Geri dönüş yasaktır', 'Tek yönlü yol'], a: 0, e: 'Mavi zemin üzerinde daire şeklindeki oklar, dönel kavşakta ada etrafında dönülmesi gerektiğini bildirir.' },
  { id: 'tc19', s: 'tc', v: 'sign:kaygan', q: 'Bu işaret neyi bildirir?', o: ['Kaygan yol', 'Virajlı yol', 'Yol çalışması', 'Gevşek malzemeli yol'], a: 0, e: 'Üçgen ve kırmızı çerçeveli levhalar tehlike uyarısıdır. Bu levha yolun kaygan olabileceğini bildirir; hız azaltılır, ani fren ve direksiyon hareketlerinden kaçınılır.' },
  { id: 'tc20', s: 'tc', v: 'sign:okul', q: 'Bu işaret neyi bildirir?', o: ['Okul geçidi', 'Yaya yolu', 'Çocuk parkı', 'Yaya giremez'], a: 0, e: 'İleride okul geçidi olduğunu bildirir. Hız azaltılır, çocukların ani hareketlerine karşı dikkatli olunur.' },
  { id: 'tc21', s: 'tc', v: 'sign:virajsag', q: 'Bu işaret neyi bildirir?', o: ['Sağa tehlikeli viraj', 'Sağa mecburi yön', 'Sağa dönülmez', 'Sağdan daralan yol'], a: 0, e: 'Tehlike uyarı levhası: ileride sağa doğru tehlikeli bir viraj var. Virajdan önce hız azaltılır.' },
  { id: 'tc22', s: 'tc', v: 'sign:daralan', q: 'Bu işaret neyi bildirir?', o: ['Her iki taraftan daralan kaplama', 'İki yönlü trafik', 'Köprü', 'Tünel'], a: 0, e: 'Yolun kaplama genişliğinin her iki taraftan daraldığını bildiren tehlike uyarı işaretidir.' },
  { id: 'tc23', s: 'tc', v: 'sign:ikiyon', q: 'Bu işaret neyi bildirir?', o: ['İki yönlü trafik', 'Tek yönlü yol', 'Sollama yasak', 'Şerit sayısı artıyor'], a: 0, e: 'Tek yönlü yolun bittiğini ve iki yönlü trafiğe geçildiğini bildiren tehlike uyarı işaretidir.' },
  { id: 'tc24', s: 'tc', v: 'sign:isikli', q: 'Bu işaret neyi bildirir?', o: ['Işıklı işaret cihazı (trafik ışığı) var', 'Yol çalışması', 'Demiryolu geçidi', 'Trafik görevlisi var'], a: 0, e: 'İleride ışıklı işaret cihazı bulunduğunu bildiren tehlike uyarı işaretidir.' },
  { id: 'tc25', s: 'tc', v: 'sign:kavsak', q: 'Bu işaret neyi bildirir?', o: ['Ana yol – tali yol kavşağı', 'Demiryolu geçidi', 'Hastane', 'Çıkmaz yol'], a: 0, e: 'Kalın çizgi ana yolu, ince çizgi tali yolu gösterir: ileride ana yol ile tali yolun kesiştiği bir kavşak var.' },
  { id: 'tc26', s: 'tc', v: 'sign:yolcalisma', q: 'Bu işaret neyi bildirir?', o: ['Yol çalışması', 'Yaya geçidi', 'Kaygan yol', 'Düşebilecek taşlar'], a: 0, e: 'İleride yol çalışması olduğunu bildirir; hız azaltılır, işaretçilere ve çalışanlara dikkat edilir.' },
  { id: 'tc27', s: 'tc', v: 'sign:cikmaz', q: 'Bu işaret neyi bildirir?', o: ['Çıkmaz yol', 'Tek yönlü yol', 'Hastane', 'Park yeri'], a: 0, e: 'Mavi zeminli bilgi işaretidir; yolun ilerisinin kapalı, yani çıkmaz yol olduğunu bildirir.' },
  { id: 'tc28', s: 'tc', v: 'sign:tekyon', q: 'Bu işaret neyi bildirir?', o: ['Tek yönlü yol', 'İleri mecburi yön', 'Ana yol', 'Otoyol'], a: 0, e: 'Mavi zemin üzerindeki beyaz ok, tek yönlü yolu bildiren bir bilgi işaretidir.' },
  { id: 'tc29', s: 'tc', v: 'sign:hastane', q: 'Bu işaret neyi bildirir?', o: ['Hastane', 'Otel', 'Eczane', 'Havaalanı'], a: 0, e: 'Hastane bilgi işaretidir; yakında hastane olduğunu, gürültü yapmamaya ve dikkatli olmaya özen gösterilmesi gerektiğini bildirir.' },
  { id: 'tc30', s: 'tc', v: 'sign:yerlesim', q: 'Yerleşim yeri içinde, aksine bir işaret yoksa otomobiller için azami hız kaç km/s’tir?', fix: 1, o: ['30', '50', '70', '90'], a: 1, e: 'Yerleşim yeri içinde otomobiller için azami hız 50 km/s’tir.' },
  { id: 'tc31', s: 'tc', fix: 1, q: 'Yerleşim yeri dışındaki iki yönlü (bölünmemiş) yollarda otomobiller için azami hız kaç km/s’tir?', o: ['70', '90', '110', '120'], a: 1, e: 'Yerleşim yeri dışındaki iki yönlü yollarda otomobiller için azami hız 90 km/s’tir.' },
  { id: 'tc32', s: 'tc', fix: 1, q: 'Yerleşim yeri dışındaki bölünmüş yollarda otomobiller için azami hız kaç km/s’tir?', o: ['90', '100', '110', '130'], a: 2, e: 'Bölünmüş yollarda otomobiller için azami hız 110 km/s’tir.' },
  { id: 'tc33', s: 'tc', fix: 1, q: 'Otoyollarda, aksine bir işaret yoksa otomobiller için azami hız kaç km/s’tir?', o: ['100', '110', '120', '140'], a: 2, e: 'Otoyollarda otomobiller için azami hız 120 km/s’tir.' },
  { id: 'tc34', s: 'tc', q: 'Trafik görevlisinin işareti ile trafik ışığı farklı şeyler gösteriyorsa sürücü hangisine uyar?', o: ['Trafik görevlisine', 'Trafik ışığına', 'Trafik levhalarına', 'Kendi değerlendirmesine'], a: 0, e: 'Uyma sırası: trafik görevlisi, ışıklı işaretler, trafik işaretleri (levhalar) ve son olarak genel trafik kuralları.' },
  { id: 'tc35', s: 'tc', v: 'scene:kavsak-sag', q: 'Şekildeki ışıksız ve levhasız kavşağa A ve B araçları aynı anda geliyor. İlk geçiş hakkı hangisinindir?', o: ['B aracının; A’ya göre sağdan geliyor', 'A aracının; düz gidiyor', 'Hangisi daha hızlıysa onun', 'Hangisi önce korna çalarsa onun'], a: 0, e: 'İşaretsiz kavşaklarda sağdan gelen araca yol verilir. A aracına göre B sağdan geldiği için önce B geçer.' },
  { id: 'tc36', s: 'tc', v: 'scene:anayol-tali', q: 'Şekilde ana yoldaki A aracı ile “Yol ver” levhası bulunan tali yoldaki B aracı kavşağa yaklaşıyor. İlk geçiş hakkı hangisinindir?', o: ['A aracının; tali yoldan gelen, ana yoldaki araca yol verir', 'B aracının; A’ya göre sağdan geliyor', 'Kavşağa önce hangisi girerse onun', 'İkisi de durup beklemelidir'], a: 0, e: 'Levhalar genel kuraldan önce gelir. Sağdan gelse de “Yol ver” levhalı tali yoldaki B, ana yoldaki A’ya yol verir.' },
  { id: 'tc37', s: 'tc', v: 'scene:donel', q: 'Şekildeki dönel kavşakta, kavşağın içindeki A aracı ile kavşağa girmek isteyen B aracından hangisinin geçiş hakkı vardır?', o: ['Kavşağın içindeki A aracının', 'Kavşağa girmek isteyen B aracının', 'Sağdan gelen aracın', 'Büyük olan aracın'], a: 0, e: 'Dönel kavşaklarda, aksine bir işaret yoksa kavşak içinde dönmekte olan araç önceliklidir; kavşağa giren araç yol verir.' },
  { id: 'tc38', s: 'tc', v: 'scene:sola-donus', q: 'Şekilde sola dönmek isteyen A aracı ile karşı yönden düz gelen B aracı kavşağa aynı anda geliyor. Geçiş sırası nasıl olmalıdır?', o: ['Önce B geçer, sonra A sola döner', 'Önce A döner, sonra B geçer', 'İki araç aynı anda geçer', 'Önce korna çalan geçer'], a: 0, e: 'Sola dönen araç, karşı yönden gelip düz giden veya sağa dönen araçlara yol verir.' },
  { id: 'tc39', s: 'tc', v: 'scene:ambulans', q: 'Şekildeki gibi arkadan ışıklı ve sesli uyarı işaretlerini çalıştırarak bir ambulans yaklaşıyorsa sürücü ne yapmalıdır?', o: ['Yolun sağına yanaşıp yavaşlamalı, gerekirse durarak yol vermeli', 'Hızlanarak ambulansın önünden kaçmalı', 'Sol şeride geçip durmalı', 'Olduğu yerde aniden fren yapmalı'], a: 0, e: 'Geçiş üstünlüğü olan araçlara, sağa yanaşarak ve gerekirse durarak yol verilir. Ani fren ve beklenmedik manevralar kazaya yol açabilir.' },
  { id: 'tc40', s: 'tc', v: 'scene:yaya-gecidi', q: 'Şekildeki gibi yaya geçidinde karşıya geçen bir yaya varsa sürücü ne yapmalıdır?', o: ['Durup yayaya yol vermeli', 'Korna çalarak yayayı uyarmalı', 'Hızlanıp yayadan önce geçmeli', 'Selektör yaparak geçmeli'], a: 0, e: 'Yaya geçitlerinde öncelik yayalarındır; sürücü yavaşlar, gerekirse durarak yayanın geçmesini bekler.' },
  { id: 'tc41', s: 'tc', v: 'scene:cizgi-kesikduz', q: 'Şekilde yolun ortasında kırmızı aracın tarafında kesik, karşı tarafta düz çizgi var. Kırmızı araç için hangisi doğrudur?', o: ['Karşı şerit boş ve görüş yeterliyse traktörü sollayabilir', 'Düz çizgi olduğu için hiçbir şekilde sollayamaz', 'Yalnızca korna çalarak sollayabilir', 'Yalnızca sağdan sollayabilir'], a: 0, e: 'Kesik ve düz çizgi yan yana ise sürücü kendi tarafındaki çizgiye göre davranır. Kırmızı aracın tarafında kesik çizgi olduğu için güvenliyse sollayabilir.' },
  { id: 'tc42', s: 'tc', v: 'scene:cizgi-duzkesik', q: 'Şekilde yolun ortasında kırmızı aracın tarafında düz, karşı tarafta kesik çizgi var. Kırmızı araç için hangisi doğrudur?', o: ['Sollama yapamaz; kendi tarafındaki düz çizgiyi geçemez', 'Karşı taraf kesik olduğu için sollayabilir', 'Traktör yavaş olduğu için sollayabilir', 'Sinyal vererek sollayabilir'], a: 0, e: 'Sürücü kendisine yakın olan çizgiye uyar. Kendi tarafında düz çizgi bulunan araç çizgiyi geçemez, sollama yapamaz.' },
  { id: 'tc43', s: 'tc', v: 'scene:cizgi-cift', q: 'Şekildeki gibi yolun ortasında çift düz çizgi bulunan yolda sürücü ne yapmalıdır?', o: ['Çizgiyi hiçbir şekilde geçmemeli, sollama yapmamalı', 'Karşı şerit boşsa sollayabilir', 'Kısa bir süreliğine çizginin üzerinden gidebilir', 'Yalnızca gündüz sollayabilir'], a: 0, e: 'Çift düz çizgi, iki yönlü yolda karşı yönlerdeki trafiği ayırır; hiçbir şekilde üzerinden geçilmez.' },
  { id: 'tc44', s: 'tc', fix: 1, q: 'Kuru ve normal bir yolda 90 km/s hızla giden otomobilin öndeki araçla arasında bırakması gereken en az takip mesafesi yaklaşık kaç metredir?', o: ['10', '20', '45', '90'], a: 2, e: 'Takip mesafesi, hızın (km/s) yarısı kadar metre olarak hesaplanır: 90 km/s için en az 45 metre. Yağışlı ve kaygan yolda bu mesafe artırılır.' },
  { id: 'tc45', s: 'tc', q: 'Sollama (öndeki aracı geçme) kural olarak hangi taraftan yapılır?', o: ['Soldan', 'Sağdan', 'Banketten', 'Uygun olan her iki taraftan'], a: 0, e: 'Sollama kural olarak soldan yapılır. Sağdan sollama ancak çok şeritli yollarda şerit izleme gibi özel durumlarda söz konusudur.' },
  { id: 'tc46', s: 'tc', q: 'Aşağıdakilerden hangisinde sollama yapmak yasaktır?', o: ['Görüşün yetersiz olduğu tepe üstlerinde', 'Kesik yol çizgisi bulunan, görüşün açık olduğu düz yolda', 'Karşı yönün boş olduğu, kesik çizgili yolda', 'Çok şeritli bölünmüş yolda, soldaki şerit boşken'], a: 0, e: 'Tepe üstleri, virajlar, kavşaklar, yaya ve demiryolu geçitleri gibi görüşün yetersiz ya da tehlikenin fazla olduğu yerlerde sollama yapılmaz.' },
  { id: 'tc47', s: 'tc', q: 'Yeşil ışık yanarken kavşağın karşı tarafı araçlarla dolu ise sürücü ne yapmalıdır?', o: ['Kavşağa girmeden, trafiği tıkamayacak şekilde beklemeli', 'Kavşağın ortasına kadar ilerleyip beklemeli', 'Korna çalarak araçları uyarmalı', 'Karşı şeride geçerek ilerlemeli'], a: 0, e: 'Yeşil ışık yansa bile, kavşağın içinde kalıp diğer yönlerin trafiğini tıkayacaksa sürücü kavşağa girmez.' },
  { id: 'tc48', s: 'tc', q: 'Trafik ışıklarında kırmızı ve sarı ışık birlikte yandığında sürücü ne yapmalıdır?', o: ['Hazırlanmalı ama yeşil yanmadan geçmemeli', 'Hemen geçmeli', 'Geri gitmeli', 'Dörtlü flaşörleri yakmalı'], a: 0, e: 'Kırmızı ile sarının birlikte yanması, yeşilin yanmak üzere olduğunu bildirir. Sürücü hazırlanır; ancak yeşil yanmadan hareket etmez.' },
  { id: 'tc49', s: 'tc', q: 'Yanıp sönen sarı ışığın bulunduğu kavşağa yaklaşan sürücü ne yapmalıdır?', o: ['Hızını azaltıp dikkatli bir şekilde geçmeli', 'Mutlaka durup beklemeli', 'Hızını artırarak geçmeli', 'Geri dönmeli'], a: 0, e: 'Yanıp sönen sarı ışık dikkat anlamına gelir: sürücü yavaşlar, kavşağı kontrol ederek dikkatle geçer.' },
  { id: 'tc50', s: 'tc', q: 'Kavşakta sağa dönecek sürücü dönüşe hangi şeritten başlamalıdır?', o: ['En sağ şeritten', 'En sol şeritten', 'Orta şeritten', 'Herhangi bir şeritten'], a: 0, e: 'Sağa dönecek sürücü önceden sinyal vererek en sağ şeride girer ve dönüşü kısa bir kavisle yapar.' },
  { id: 'tc51', s: 'tc', q: 'Şerit değiştirmeden önce hangi sıra izlenmelidir?', o: ['Ayna kontrolü → sinyal → omuz kontrolü → manevra', 'Manevra → sinyal → ayna', 'Sinyal → manevra → ayna', 'Korna → manevra → sinyal'], a: 0, e: 'Önce aynalarla arkadaki trafik kontrol edilir, sinyal verilir, kör nokta omuz üzerinden kontrol edilir ve güvenliyse şerit değiştirilir.' },
  { id: 'tc52', s: 'tc', q: 'Yerleşim yeri içinde, yaya geçitlerinde ve kavşaklara 5 metre mesafe içinde aşağıdakilerden hangisi yasaktır?', o: ['Duraklamak ve park etmek', 'Yavaşlamak', 'Sinyal vermek', 'Kısa hüzmeli far yakmak'], a: 0, e: 'Yaya ve okul geçitlerinde, kavşaklarda ve yerleşim yeri içinde bunlara 5 metre mesafe içinde duraklamak yasaktır; duraklamanın yasak olduğu yerde park da yasaktır.' },
  { id: 'tc53', s: 'tc', fix: 1, q: 'Otobüs gibi kamu hizmeti yapan yolcu taşıtlarının duraklarını belirten levhalara iki yönden kaç metre mesafe içinde park etmek yasaktır?', o: ['5', '10', '15', '50'], a: 2, e: 'Kamu hizmeti yapan yolcu taşıtlarının duraklarını belirten levhalara iki yönden 15 metre mesafe içinde park edilmez.' },
  { id: 'tc54', s: 'tc', fix: 1, q: 'Belirlenmiş yangın musluklarına her iki yönden kaç metre mesafe içinde park etmek yasaktır?', o: ['5', '15', '25', '50'], a: 0, e: 'Yangın musluklarına her iki yönden 5 metre mesafe içinde park edilmez; itfaiyenin musluğa ulaşması engellenmemelidir.' },
  { id: 'tc55', s: 'tc', q: 'Aşağıdakilerden hangisi park etmenin yasak olduğu yerlerden biridir?', o: ['Garaj ve otopark gibi geçiş yollarının önü', 'Park yeri levhasının gösterdiği alan', 'Duraklama ve park yasağı olmayan cadde kenarı', 'Otopark içindeki boş park yeri'], a: 0, e: 'Taşıtların giriş çıkışını sağlayan geçiş yollarının önünde veya üzerinde park etmek yasaktır.' },
  { id: 'tc56', s: 'tc', q: 'Yokuş aşağı park eden bir sürücü ön tekerlekleri hangi yöne çevirmelidir?', o: ['Kaldırım (yol kenarı) tarafına', 'Yolun ortasına doğru', 'Düz bırakmalıdır', 'Fark etmez'], a: 0, e: 'Yokuş aşağı park edilirken ön tekerlekler kaldırıma doğru çevrilir, el freni çekilir; araç kayarsa kaldırıma dayanarak durur.' },
  { id: 'tc57', s: 'tc', fix: 1, q: 'Gece, karşıdan gelen bir araçla karşılaşırken uzun hüzmeli farlar en geç kaç metre kala kısa hüzmeliye çevrilir?', o: ['20', '50', '150', '500'], a: 2, e: 'Karşılaşmalarda karşıdaki sürücünün gözünü almamak için uzun hüzmeli farlar en az 150 metre kala kısa hüzmeliye çevrilir.' },
  { id: 'tc58', s: 'tc', q: 'Hemzemin demiryolu geçidinde bariyerler inmeye başlamışsa sürücü ne yapmalıdır?', o: ['Durmalı ve bariyerler tamamen kalkana kadar beklemeli', 'Hızlanıp geçmeli', 'Korna çalarak geçmeli', 'Bariyerin açık kısmından dolanarak geçmeli'], a: 0, e: 'Bariyer inerken, kapalıyken veya ışıklı-sesli uyarı çalışırken demiryolu geçidine girilmez.' },
  { id: 'tc59', s: 'tc', q: 'Tünellerde aşağıdakilerden hangisi yasaktır?', o: ['Duraklamak, park etmek ve geri dönmek', 'Kısa hüzmeli farları yakmak', 'Şeridini izleyerek gitmek', 'Hız sınırına uymak'], a: 0, e: 'Tünellerde duraklamak, park etmek, geri dönmek ve sollamak yasaktır; kısa hüzmeli farlar yakılır.' },
  { id: 'tc60', s: 'tc', fix: 1, q: 'Hususi otomobil sürücüleri için yasal kandaki alkol sınırı kaç promildir?', o: ['0,00', '0,20', '0,50', '1,00'], a: 2, e: 'Hususi otomobil sürücüleri için sınır 0,50 promildir; ticari araç ve kamu hizmeti sürücüleri için 0,20 promildir. En güvenlisi hiç içmeden araç kullanmaktır.' },
  { id: 'tc61', s: 'tc', fix: 1, q: 'B sınıfı sürücü belgesi alabilmek için en az kaç yaşını doldurmuş olmak gerekir?', o: ['17', '18', '19', '21'], a: 1, e: 'B sınıfı sürücü belgesi için 18 yaşını doldurmuş olmak gerekir.' },
  { id: 'tc62', s: 'tc', fix: 1, q: 'İlk kez sürücü belgesi alanlar için belge kaç yıl süreyle “aday sürücü belgesi” niteliğindedir?', o: ['1', '2', '3', '5'], a: 1, e: 'İlk kez alınan sürücü belgesi 2 yıl süreyle aday sürücü belgesidir. Bu sürede 75 ceza puanını dolduranların belgesi iptal edilir.' },
  { id: 'tc63', s: 'tc', q: 'Ölümlü veya yaralanmalı bir trafik kazasına karışan sürücü ne yapmalıdır?', o: ['Olay yerinde kalıp yaralılara yardım etmeli ve yetkililere haber vermeli', 'Aracını çekip olay yerinden ayrılmalı', 'Yaralıları kendi aracıyla mutlaka taşımalı', 'Kaza raporu için ertesi gün başvurmalı'], a: 0, e: 'Yaralanmalı kazaya karışan sürücü olay yerinden ayrılmaz; yaralılara ilk yardım sağlanır, 112 ve 155/156 aranarak yetkililere haber verilir.' },
  { id: 'tc64', s: 'tc', q: 'Yalnızca maddi hasarlı bir trafik kazasında sürücüler ne yapmalıdır?', o: ['Durumu tespit edip (tutanak, fotoğraf) araçları trafiği aksatmayacak şekilde yoldan çekmeli', 'Polis gelene kadar araçları kesinlikle yerinden oynatmamalı', 'Kaza yerinden haber vermeden ayrılmalı', 'Trafiği bekleterek hasarı yolda tartışmalı'], a: 0, e: 'Maddi hasarlı kazalarda kaza tespit tutanağı düzenlenir ve araçlar trafiği tehlikeye düşürmeyecek şekilde yoldan kaldırılır.' },
  { id: 'tc65', s: 'tc', q: 'Otoyollarda emniyet şeridi hangi durumda kullanılabilir?', o: ['Arıza veya acil durumlarda duraklamak için', 'Trafik sıkıştığında ilerlemek için', 'Sollama yapmak için', 'Mola vermek için'], a: 0, e: 'Emniyet şeridi yalnızca arıza, kaza gibi acil durumlarda ve geçiş üstünlüğüne sahip araçlar için kullanılır.' },
  { id: 'tc66', s: 'tc', q: 'Karayolunun taşıt yolu dışında kalan, kaplamalı veya kaplamasız kısmına ne denir?', o: ['Banket', 'Refüj', 'Şerit', 'Platform'], a: 0, e: 'Banket, karayolunun taşıt yolu dışında kalan kaplamalı veya kaplamasız kısmıdır.' },
  { id: 'tc67', s: 'tc', q: 'Karşılıklı gidiş ve gelişin bir ayırıcı (refüj) ile ayrıldığı yola ne denir?', o: ['Bölünmüş yol', 'Tek yönlü yol', 'Ana yol', 'Tali yol'], a: 0, e: 'Gidiş ve geliş yönleri refüj, bariyer gibi bir ayırıcıyla birbirinden ayrılmış yola bölünmüş yol denir.' },

  /* ================= ARAÇ TEKNİĞİ ================= */
  { id: 'at01', s: 'at', v: 'lamp:yag', q: 'Sürüş sırasında bu uyarı ışığı yanarsa ne yapılmalıdır?', o: ['Güvenli bir yerde durulup motor kapatılmalı, yağ seviyesi kontrol edilmeli', 'Sürüşe normal şekilde devam edilmeli', 'Motor yüksek devirde çalıştırılmalı', 'Klima kapatılmalı'], a: 0, e: 'Kırmızı yağ lambası motor yağ basıncının düştüğünü gösterir. Yağsız çalışan motor kısa sürede ağır hasar görür; hemen durulmalıdır.' },
  { id: 'at02', s: 'at', v: 'lamp:aku', q: 'Motor çalışırken bu uyarı ışığının yanması neyi gösterir?', o: ['Şarj sisteminde (alternatör, kayış veya akü) arıza olduğunu', 'Motor yağının azaldığını', 'Kapının açık olduğunu', 'Fren balatasının aşındığını'], a: 0, e: 'Akü lambası motor çalışırken yanıyorsa akü şarj edilmiyor demektir; alternatör veya kayış arızası olabilir.' },
  { id: 'at03', s: 'at', v: 'lamp:hararet', q: 'Bu uyarı ışığı neyi bildirir?', o: ['Motor soğutma suyu sıcaklığının çok yükseldiğini (hararet)', 'Yakıtın azaldığını', 'Lastik basıncının düştüğünü', 'Klimanın arızalandığını'], a: 0, e: 'Hararet lambası motorun aşırı ısındığını gösterir. Güvenli bir yerde durulur; soğutma sistemi motor soğuduktan sonra kontrol edilir.' },
  { id: 'at04', s: 'at', v: 'lamp:fren', q: 'El freni indirildiği hâlde bu ışık yanmaya devam ediyorsa ne anlaşılır?', o: ['Fren hidroliği seviyesi düşük veya fren sisteminde arıza olabilir', 'Yakıtın azaldığı', 'Uzun farların yandığı', 'Motorun henüz ısınmadığı'], a: 0, e: 'Kırmızı fren lambası el freni çekiliyken yanar. El freni indirildiği hâlde sönmüyorsa hidrolik seviyesi düşük veya fren sistemi arızalı olabilir.' },
  { id: 'at05', s: 'at', v: 'lamp:abs', q: 'Göstergede bu uyarı lambası bulunan ABS sistemi ne işe yarar?', o: ['Ani frenlemede tekerleklerin kilitlenmesini önler', 'Yakıt tüketimini azaltır', 'Motor hararetini düşürür', 'Lastik basıncını ölçer'], a: 0, e: 'ABS ani frenlemede tekerleklerin kilitlenmesini önler; böylece fren yaparken direksiyon hâkimiyeti korunur.' },
  { id: 'at06', s: 'at', v: 'lamp:motor', q: 'Sürüş sırasında bu uyarı ışığı yanarsa ne anlaşılır?', o: ['Motor yönetim (elektronik) sisteminde arıza var; en kısa sürede servise gidilmeli', 'Motor yağı fazla', 'Silecek suyu bitti', 'Bagaj açık'], a: 0, e: 'Sarı motor arıza lambası motor yönetim sisteminde bir sorun tespit edildiğini gösterir; araç en kısa sürede kontrol ettirilmelidir.' },
  { id: 'at07', s: 'at', v: 'lamp:kizdirma', q: 'Dizel araçlarda kontak açıldığında yanan bu ışık neyi gösterir?', o: ['Kızdırma bujilerinin motoru ön ısıttığını; ışık sönünce motor çalıştırılır', 'Motor yağının azaldığını', 'Akünün boşaldığını', 'Klimanın çalıştığını'], a: 0, e: 'Kızdırma lambası, dizel motorun kolay çalışması için yanma odasının ısıtıldığını gösterir. Işık sönünce marşa basılır.' },
  { id: 'at08', s: 'at', v: 'lamp:uzun', q: 'Göstergede yanan bu mavi ışık neyi gösterir?', o: ['Uzun hüzmeli farların yandığını', 'Kısa hüzmeli farların yandığını', 'Sis farlarının yandığını', 'Motorun soğuk olduğunu'], a: 0, e: 'Mavi far sembolü uzun hüzmeli (uzağı gösteren) farların açık olduğunu bildirir. Karşılaşmalarda ve öndeki aracı takip ederken kısa fara geçilir.' },
  { id: 'at09', s: 'at', v: 'lamp:kemer', q: 'Bu uyarı ışığı neyi bildirir?', o: ['Emniyet kemerinin takılmadığını', 'Hava yastığının açıldığını', 'Koltuk ısıtmasının açık olduğunu', 'Kapının açık olduğunu'], a: 0, e: 'Emniyet kemeri uyarısı, sürücünün veya yolcunun kemerini takmadığını bildirir.' },
  { id: 'at10', s: 'at', v: 'lamp:lastik', q: 'Bu uyarı ışığı neyi bildirir?', o: ['Lastik basıncının düştüğünü', 'Fren balatasının aşındığını', 'Yakıtın azaldığını', 'Direksiyonun kilitlendiğini'], a: 0, e: 'Lastik basınç uyarısı yanınca lastikler kontrol edilip basınç araç üreticisinin önerdiği değere getirilir.' },
  { id: 'at11', s: 'at', v: 'lamp:sisarka', q: 'Bu gösterge ışığı neyi bildirir?', o: ['Arka sis lambasının yandığını', 'Ön sis farlarının yandığını', 'Uzun farların yandığını', 'Arka camın buğusunun alındığını'], a: 0, e: 'Arka sis lambası yalnızca sis, kar, yoğun yağış gibi görüşü ciddi şekilde azaltan durumlarda yakılır; aksi hâlde arkadaki sürücülerin gözünü alır.' },
  { id: 'at12', s: 'at', fix: 1, q: 'Otomobil lastiklerinde diş derinliği en az kaç milimetre olmalıdır?', o: ['0,5', '1,6', '4', '8'], a: 1, e: 'Otomobil lastiklerinde diş derinliği en az 1,6 mm olmalıdır. Diş derinliği azaldıkça ıslak yolda yol tutuş ve fren performansı düşer.' },
  { id: 'at13', s: 'at', q: 'Motor yağ seviyesi nasıl kontrol edilir?', o: ['Araç düz zeminde ve motor durmuşken yağ çubuğuyla; seviye min–max çizgileri arasında olmalıdır', 'Motor çalışırken, yüksek devirde', 'Araç yokuştayken', 'Egzoz dumanına bakarak'], a: 0, e: 'Yağ seviyesi araç düz zemindeyken, motor durdurulup yağın karterde toplanması beklendikten sonra yağ çubuğuyla kontrol edilir.' },
  { id: 'at14', s: 'at', q: 'Motor soğutma suyuna antifriz katılmasının amacı nedir?', o: ['Donmayı önlemek ve korozyonu (paslanmayı) azaltmak', 'Motor gücünü artırmak', 'Yakıt tasarrufu sağlamak', 'Fren gücünü artırmak'], a: 0, e: 'Antifriz soğutma suyunun donma noktasını düşürür, kışın motor bloğunun çatlamasını önler ve sistemi korozyona karşı korur.' },
  { id: 'at15', s: 'at', q: 'Motor sıcakken radyatör kapağı açılırsa ne olabilir?', o: ['Basınçlı sıcak su ve buhar fışkırarak yanığa yol açabilir', 'Motor hemen soğur', 'Soğutma suyu donar', 'Hiçbir sakıncası olmaz'], a: 0, e: 'Sıcak soğutma sistemi basınç altındadır; kapak açılırsa kaynar su ve buhar fışkırır. Kapak ancak motor soğuduktan sonra açılır.' },
  { id: 'at16', s: 'at', q: 'Akü kutup başlarında oluşan oksitlenmeyi önlemek için ne yapılır?', o: ['Kutup başları temizlenip ince bir kat vazelin sürülür', 'Üzerine su dökülür', 'Boya sürülür', 'Yağlı bezle sarılır'], a: 0, e: 'Kutup başları temizlendikten sonra vazelin sürülerek oksitlenme ve temassızlık önlenir.' },
  { id: 'at17', s: 'at', q: 'Debriyaj (kavrama) sisteminin görevi nedir?', o: ['Motorun gücünü vites kutusuna iletmek veya kesmek', 'Aracı durdurmak', 'Motoru soğutmak', 'Aküyü şarj etmek'], a: 0, e: 'Debriyaj, motor ile vites kutusu arasındaki güç aktarımını keser veya sağlar; kalkışta ve vites değiştirirken kullanılır.' },
  { id: 'at18', s: 'at', q: 'Virajlarda iç ve dış tekerleklerin farklı hızlarda dönmesini sağlayan sistem hangisidir?', o: ['Diferansiyel', 'Debriyaj', 'Alternatör', 'Termostat'], a: 0, e: 'Virajda dış tekerlek daha uzun yol alır. Diferansiyel, tekerleklerin farklı hızlarda dönmesine izin vererek aracın rahat dönmesini sağlar.' },
  { id: 'at19', s: 'at', q: 'Motor çalışırken aküyü şarj eden ve aracın elektrik ihtiyacını karşılayan parça hangisidir?', o: ['Alternatör', 'Marş motoru', 'Radyatör', 'Amortisör'], a: 0, e: 'Alternatör, motor çalışırken elektrik üretir; aküyü şarj eder ve aracın elektrik ihtiyacını karşılar.' },
  { id: 'at20', s: 'at', q: 'Motorun ilk hareketini sağlayarak çalıştırılmasına yarayan parça hangisidir?', o: ['Marş motoru', 'Alternatör', 'Termostat', 'Diferansiyel'], a: 0, e: 'Marş motoru, aküden aldığı enerjiyle krank milini döndürerek motorun çalışmasını başlatır.' },
  { id: 'at21', s: 'at', q: 'Motorun kısa sürede çalışma sıcaklığına ulaşmasını sağlayan soğutma sistemi parçası hangisidir?', o: ['Termostat', 'Su pompası', 'Fan (vantilatör)', 'Radyatör kapağı'], a: 0, e: 'Termostat, motor soğukken suyun radyatöre geçişini engeller; motor çalışma sıcaklığına ulaşınca açılır.' },
  { id: 'at22', s: 'at', q: 'Yol bozukluklarından kaynaklanan sarsıntıları sönümleyen süspansiyon parçası hangisidir?', o: ['Amortisör', 'Diferansiyel', 'Şaft', 'Krank mili'], a: 0, e: 'Amortisörler yaylardaki salınımı sönümler; aracın yol tutuşunu ve sürüş konforunu sağlar. Bozuk amortisör fren mesafesini de uzatır.' },
  { id: 'at23', s: 'at', q: 'Hava filtresi tıkanırsa aşağıdakilerden hangisi olur?', o: ['Yakıt tüketimi artar, motor gücü düşer', 'Fren mesafesi kısalır', 'Akü şarj olmaz', 'Direksiyon ağırlaşır'], a: 0, e: 'Tıkalı hava filtresi motora yeterli hava gitmesini engeller; yakıt tam yanmaz, tüketim artar ve motor gücü düşer.' },
  { id: 'at24', s: 'at', q: 'Lastik hava basıncının düşük olması neye yol açar?', o: ['Yakıt tüketiminin artmasına ve lastiğin kenarlarından aşınmasına', 'Lastiğin ortasından aşınmasına', 'Fren mesafesinin kısalmasına', 'Motor gücünün artmasına'], a: 0, e: 'Düşük basınçlı lastik kenarlarından aşınır, yakıt tüketimi artar ve yol tutuş kötüleşir. Basınç fazla olursa lastik ortasından aşınır.' },
  { id: 'at25', s: 'at', q: 'Direksiyonun belli bir hızda titremesinin en olası nedeni nedir?', o: ['Tekerlek balans ayarının bozuk olması', 'Yakıtın azalması', 'Motor yağının yeni olması', 'Farların kirli olması'], a: 0, e: 'Balansı bozuk tekerlekler belirli hızlarda direksiyonda titremeye yol açar; lastikler ve ön düzen parçaları da erken yıpranır.' },
  { id: 'at26', s: 'at', q: 'Egzozdan mavi duman çıkması neyi gösterir?', o: ['Motorun yağ yaktığını', 'Yakıtın temiz yandığını', 'Soğutma suyunun fazla olduğunu', 'Akünün tam dolu olduğunu'], a: 0, e: 'Mavi duman, motor yağının yanma odasına geçip yandığını gösterir; segman veya supap arızası olabilir.' },
  { id: 'at27', s: 'at', q: 'Fren hidrolik seviyesinin çok azalması en çok neye yol açar?', o: ['Frenlerin tutmamasına', 'Motorun hararet yapmasına', 'Farların zayıflamasına', 'Yakıt tüketiminin azalmasına'], a: 0, e: 'Hidrolik frenlerde pedal kuvveti sıvı yoluyla iletilir; sıvı azalırsa frenler tutmayabilir. Seviye düzenli kontrol edilmelidir.' },

  /* ================= TRAFİK ADABI ================= */
  { id: 'ta01', s: 'ta', q: 'Kendini başkalarının yerine koyarak onların duygu ve düşüncelerini anlamaya ne denir?', o: ['Empati', 'Sempati', 'Bencillik', 'Önyargı'], a: 0, e: 'Empati, kendini karşısındakinin yerine koyabilmektir. Trafikte yayanın, yaşlının, bisikletlinin gözünden bakabilmek kazaları önler.' },
  { id: 'ta02', s: 'ta', q: 'Trafik adabı nedir?', o: ['Kurallara uymanın yanında trafikte saygı, sabır ve nezaketle davranmaktır', 'Yalnızca trafik cezalarını bilmektir', 'Aracı hızlı kullanabilmektir', 'Yalnızca yayaların uyması gereken kurallardır'], a: 0, e: 'Trafik adabı; kurallara uymanın ötesinde diğer yol kullanıcılarına saygı, hoşgörü, sabır ve nezaketle davranmayı kapsar.' },
  { id: 'ta03', s: 'ta', q: 'Yağmurlu havada kaldırım kenarındaki su birikintisine yaklaşan sürücü ne yapmalıdır?', o: ['Yayaları ıslatmamak için yavaşlamalı', 'Hızını korumalı', 'Korna çalmalı', 'Birikintinin üzerinden hızla geçmeli'], a: 0, e: 'Su birikintisinden hızla geçmek yayaları ıslatır ve aracın kaymasına yol açabilir. Nazik sürücü yavaşlar.' },
  { id: 'ta04', s: 'ta', q: 'Aşağıdakilerden hangisi trafik adabına aykırıdır?', o: ['Gereksiz yere korna çalmak', 'Sinyal vererek şerit değiştirmek', 'Yol veren sürücüye el ile teşekkür etmek', 'Yayaya yol vermek'], a: 0, e: 'Korna yalnızca tehlikeyi önlemek için kısa süreli kullanılır. Gereksiz korna gürültü kirliliği yaratır ve diğer insanları rahatsız eder.' },
  { id: 'ta05', s: 'ta', q: 'Trafikte kendisine hata yapan bir sürücüye karşı en doğru davranış hangisidir?', o: ['Sakin kalmak ve hoşgörülü davranmak', 'Selektör ve korna ile tepki göstermek', 'Önüne geçip ani fren yapmak', 'Peşinden gidip hesap sormak'], a: 0, e: 'Öfkeyle verilen tepkiler tehlikeli durumlar yaratır. Sakin kalmak, herkesin hata yapabileceğini kabul etmek güvenli sürüşün parçasıdır.' },
  { id: 'ta06', s: 'ta', q: 'Engelliler için ayrılmış park yerine engelli olmayan bir sürücünün park etmesi hakkında hangisi doğrudur?', o: ['Hem yasaktır hem de trafik adabına aykırıdır', 'Kısa süreli olursa uygundur', 'Gece saatlerinde uygundur', 'Başka boş yer yoksa uygundur'], a: 0, e: 'Engelli park yerleri, bu yerlere gerçekten ihtiyaç duyanlar içindir. Buraya park etmek kanunen yasak ve saygısızlıktır.' },
  { id: 'ta07', s: 'ta', q: 'Uzun yolda yorgunluk ve uyku hissi olan sürücü ne yapmalıdır?', o: ['Güvenli bir yerde mola verip dinlenmelidir', 'Hızını artırıp bir an önce varmalıdır', 'Camı açıp yola devam etmelidir', 'Yüksek sesle müzik dinleyerek devam etmelidir'], a: 0, e: 'Yorgunluk tepki süresini uzatır, dikkatini dağıtır. Uykusu gelen sürücü güvenli bir yerde durup dinlenmelidir.' },
  { id: 'ta08', s: 'ta', q: 'Sürüş sırasında cep telefonunu elde tutarak konuşmakla ilgili hangisi doğrudur?', o: ['Dikkati dağıtır ve yasaktır', 'Kısa konuşmalarda sakıncası yoktur', 'Yalnızca şehir içinde serbesttir', 'Trafik sıkışıkken uygundur'], a: 0, e: 'Sürüş sırasında telefonu elde tutarak konuşmak veya mesajlaşmak yasaktır; dikkati dağıtır ve kaza riskini artırır.' },
  { id: 'ta09', s: 'ta', q: 'Araçtan dışarı çöp atmak hakkında hangisi doğrudur?', o: ['Çevreyi kirletir; trafik adabına ve kurallara aykırıdır', 'Aracın içini temiz tuttuğu için doğrudur', 'Otoyolda sakıncası yoktur', 'Gece yapılırsa sorun olmaz'], a: 0, e: 'Araçtan atılan çöp çevreyi kirletir, diğer sürücüleri tehlikeye atabilir ve yangına yol açabilir.' },
  { id: 'ta10', s: 'ta', q: 'Aşağıdakilerden hangisi çevre kirliliğini azaltan doğru bir sürücü davranışıdır?', o: ['Aracın bakımını düzenli yaptırmak ve gereksiz yere rölantide beklememek', 'Motoru sürekli yüksek devirde çalıştırmak', 'Egzoz emisyon ölçümünü ertelemek', 'Atık motor yağını toprağa dökmek'], a: 0, e: 'Bakımlı araç daha az yakıt harcar, daha az egzoz gazı çıkarır. Atık yağ ve akü gibi atıklar toplama noktalarına verilmelidir.' },
  { id: 'ta11', s: 'ta', q: 'Yeşil ışık yandığı hâlde karşıya geçişini tamamlayamamış yaşlı bir yayaya sürücü nasıl davranmalıdır?', o: ['Yayanın geçişini tamamlamasını sabırla beklemelidir', 'Korna çalarak yayayı acele ettirmelidir', 'Yayanın yanından hızla geçmelidir', 'Selektör yaparak uyarmalıdır'], a: 0, e: 'Işık yeşile dönse de geçişini tamamlamamış yayalara yol verilir. Yaşlı, engelli ve çocuk yayalara karşı özellikle sabırlı olunmalıdır.' },
  { id: 'ta12', s: 'ta', q: 'Sollanmakta olan bir aracın sürücüsü nasıl davranmalıdır?', o: ['Hızını artırmamalı, gerekirse sağa yanaşarak kolaylık sağlamalıdır', 'Hızını artırarak sollamayı engellemelidir', 'Sola kayarak yolu kapatmalıdır', 'Selektör yaparak tepki göstermelidir'], a: 0, e: 'Sollanan aracın sürücüsü hızını artıramaz; sağa yanaşarak sollamanın güvenle tamamlanmasına yardımcı olur.' },
  { id: 'ta13', s: 'ta', q: 'Gece şehir içinde, öndeki aracı yakından takip eden sürücü farlarını nasıl kullanmalıdır?', o: ['Kısa hüzmeli farları kullanmalıdır', 'Uzun hüzmeli farları yakmalıdır', 'Sürekli selektör yapmalıdır', 'Farları kapatmalıdır'], a: 0, e: 'Öndeki aracı takip ederken uzun far, öndeki sürücünün aynalarından gözünü alır. Kısa hüzmeli far kullanılır.' },
  { id: 'ta14', s: 'ta', q: 'Okul bölgesinde çocukların bulunduğu bir alanda sürücü nasıl davranmalıdır?', o: ['Hızını azaltıp çocukların ani hareketlerine karşı hazırlıklı olmalıdır', 'Korna çalarak çocukları uyarmalıdır', 'Hızını koruyup dikkatli olmalıdır', 'Çocukların kendisine yol vermesini beklemelidir'], a: 0, e: 'Çocuklar tehlikeyi yetişkinler gibi fark edemez ve aniden yola çıkabilir. Okul bölgelerinde hız azaltılır, dikkat artırılır.' },
  { id: 'ta15', s: 'ta', q: 'Trafik sıkışıklığında emniyet şeridinden ilerleyen sürücü için hangisi söylenebilir?', o: ['Başkalarının hakkına saygı göstermiyor ve kural ihlali yapıyor', 'Zamanı iyi kullanıyor', 'Trafiğin açılmasına yardım ediyor', 'Doğru bir davranış sergiliyor'], a: 0, e: 'Emniyet şeridi ambulans, itfaiye gibi acil durum araçlarının yoludur. Burayı kullanmak hem yasak hem de diğer sürücülere haksızlıktır.' },
  { id: 'ta16', s: 'ta', q: 'Geçiş üstünlüğüne sahip bir ambulansa hemen yol vermek hangi değerin göstergesidir?', o: ['Sorumluluk ve duyarlılığın', 'Aceleciliğin', 'Bencilliğin', 'Kayıtsızlığın'], a: 0, e: 'Ambulansa yol vermek, bir insanın hayatının söz konusu olabileceğini bilen sorumlu ve duyarlı bir sürücünün davranışıdır.' },
  { id: 'ta17', s: 'ta', q: 'Yaya geçidine yaklaşan sürücünün trafik adabına uygun davranışı hangisidir?', o: ['Yavaşlayıp gerekirse durarak yayaya öncelik tanımak', 'Selektör yapıp yayayı beklemesi için uyarmak', 'Korna çalıp hızlanmak', 'Yayaların arasından geçmek'], a: 0, e: 'Yaya geçidinde öncelik yayalarındır. Sürücü yavaşlar ve yayanın rahatça geçebileceğini göstererek durur.' }
];
